def biGraph(n: int, e: int, arr: list[int]) -> int:
    if n == 2:
        return 1

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for i in range(0, len(arr), 2):
        u, v = arr[i], arr[i+1]
        adj[u].append(v)
        adj[v].append(u)

    # Check if the graph is connected
    visited = [False] * n
    stack = [0]
    visited[0] = True
    count = 1

    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                count += 1
                stack.append(v)

    if count != n:
        return 0

    # Check for articulation points using Tarjan's algorithm
    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n
    time = 0
    is_articulation = [False] * n

    def dfs(u):
        nonlocal time
        children = 0
        disc[u] = low[u] = time
        time += 1

        for v in adj[u]:
            if disc[v] == -1:
                parent[v] = u
                children += 1
                dfs(v)
                low[u] = min(low[u], low[v])

                if parent[u] == -1 and children > 1:
                    is_articulation[u] = True
                if parent[u] != -1 and low[v] >= disc[u]:
                    is_articulation[u] = True
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

    for u in range(n):
        if disc[u] == -1:
            dfs(u)
            if is_articulation[u]:
                return 0

    return 1
